 async exportTopic(id){if(!await this.leave())return;const choice=await this.form('导出主题 · Markdown',[{key:'ai',label:'导出内容',options:[['no','默认内容 · 保留原话与人工修改'],['yes','默认内容 + 已保存的 AI整理']]}]);if(!choice)return;const topic=await request('GET_LIBRARY_TOPIC',{id}),parts=['# '+topic.name+'\n\n'];let cursor=null,lastSection=null;do{const page=await request('TOPIC_DOCUMENT_PAGE',{options:{topicId:id,sort:this.readingSort,cursor,limit:100}});for(const item of page.items){if(lastSection!==item.placement.sectionId){const section=page.sections.find(s=>s.sectionId===item.placement.sectionId);parts.push('## '+(section?.title||'正文')+'\n\n');lastSection=item.placement.sectionId;}const e=item.entry.large?await request('GET_LIBRARY_ENTRY',{id:item.entry.id}):item.entry,time=item.entry.sourceSentAt||(e.provenanceType==='user_created'?e.createdAt:null);parts.push((time?new Date(time).toLocaleDateString('zh-CN')+'\n\n':'')+e.body+'\n\n'+(e.note?'备注：'+e.note+'\n\n':''));}cursor=page.nextCursor;}while(cursor);if(choice.ai==='yes'){const cached=(await request('GET_AI_PRESENTATION_STATUS')).topics.find(t=>t.topicId===id)?.presentation;if(cached){parts.push('---\n\n## AI整理（已保存）\n\n');for(const [field,label]of Object.entries({blockSummary:'主题速览',currentView:'当前理解',keyInformation:'核心信息',decisions:'重要决定',preferences:'偏好与原则',judgments:'判断',openQuestions:'待解决问题',possibleEvolution:'可能变化'})){const value=cached[field],text=Array.isArray(value)?value.map(x=>'- '+x.text).join('\n'):value;if(text)parts.push('### '+label+'\n\n'+text+'\n\n');}}}downloadParts(parts,'PAIA-Topic-'+topic.name.replace(/[\\/:*?"<>|]/g,'_').slice(0,80)+'.md','text/markdown');this.onStatus('主题已导出到 Markdown');await this.refresh();}
 async mergeTopic(){const topics=(await this.topics()).filter(t=>t.id!==this.id);if(!topics.length){this.onStatus('先创建另一个主题，再选择保留的主题。');return;}const value=await this.form('合并主题 · 选择保留的主题',[{key:'survivorId',label:'保留主题',options:topics.map(t=>[t.id,t.name])}]);if(!value)return;await this.mutate(async()=>{const source=await request('GET_LIBRARY_TOPIC',{id:this.id}),target=await request('GET_LIBRARY_TOPIC',{id:value.survivorId});const r=await this.checked('START_LIBRARY_LAYOUT',{layout:{kind:'topic_merge',topicId:source.id,survivorId:target.id,expectedTopicRevision:source.organizationRevision,expectedSurvivorRevision:target.organizationRevision,operationId:op()}});await this.waitLayout(r.jobId);this.id=target.id;});}
