 async loadUnplacedNext(){const collection=this.unplacedCollection;if($('thought-panel').hidden||this.id||!collection||collection.loading||collection.terminal||$('library-unplaced-list').hidden)return;const state=await collection.loadNext();if(collection!==this.unplacedCollection)return;this.renderUnplaced(state);}
 async unplaced(){const list=$('library-unplaced-list'),trigger=$('library-unplaced');if(!list.hidden&&this.unplacedCollection){list.hidden=true;trigger.setAttribute('aria-expanded','false');return;}list.hidden=false;trigger.setAttribute('aria-expanded','true');this.unplacedCollection=this.unplacedCollection||this.createUnplacedCollection();const state=await this.unplacedCollection.loadUntil({minItems:1,maxLoads:20});this.renderUnplaced(state);}
